import fs from 'node:fs'
import path from 'node:path'

const migrationsDir = path.resolve('db/migrations')
const journalPath = path.join(migrationsDir, 'meta', '_journal.json')
const outputPath = path.join(migrationsDir, 'migrations.js')

const journal = JSON.parse(fs.readFileSync(journalPath, 'utf8'))
const entries = journal.entries ?? []

const imports = entries
    .map((entry, index) => {
        const id = String(index).padStart(4, '0')
        return `import m${id} from './${entry.tag}.sql';`
    })
    .join('\n')

const mapping = entries
    .map((_, index) => {
        const id = String(index).padStart(4, '0')
        return `      m${id}`
    })
    .join(',\n')

const source = `// This file is required for Expo/React Native SQLite migrations.
// Generated by scripts/update-migrations-bundle.mjs. Do not hand-edit.

import journal from './meta/_journal.json';
${imports}

export default {
  journal,
  migrations: {
${mapping}
  }
}
`

fs.writeFileSync(outputPath, source)
console.log(`Updated ${outputPath} with ${entries.length} migrations`)
